import { readFile, writeFile } from "node:fs/promises";
const credits = JSON.parse(await readFile(".stock-portraits.json", "utf8"));
const src = await readFile("src/data/providers.ts", "utf8");
const name = (id) => {
  const i = src.indexOf(`id: "${id}"`);
  if (i < 0) return id;
  const m = src.slice(i, i + 400).match(/name: "([^"]+)"/);
  return m ? m[1] : id;
};
await writeFile(
  "src/data/portraitCredits.ts",
  `/**
 * Who photographed each driver and guide.
 *
 * GENERATED by \`node scripts/fetch-stock-portraits.mjs\`.
 *
 * The Pexels licence does not require attribution. This is here anyway, because
 * the alternative is forty photographers whose work fronts a product and who are
 * named nowhere in it — and because the promise to credit them was made when the
 * key was asked for.
 *
 * These are stock photographs of models who signed a release permitting exactly
 * this use. They are not the actual service providers, which is what the mark on
 * the image and the line at the foot of every list both say.
 */
export interface PortraitCredit {
  photographer: string;
  photographerUrl: string;
  /** The listing on Pexels, for anybody who wants the original. */
  url: string;
}

export const PORTRAIT_CREDITS: Record<string, PortraitCredit> = {
${credits
  .map(
    (c) =>
      `  /* ${name(c.id)} */\n  "${c.id}": {\n    photographer: ${JSON.stringify(c.photographer)},\n    photographerUrl: ${JSON.stringify(c.photographerUrl)},\n    url: ${JSON.stringify(c.url)},\n  },`,
  )
  .join("\n")}
};

export const portraitCredit = (providerId: string): PortraitCredit | undefined =>
  PORTRAIT_CREDITS[providerId];
`,
  "utf8",
);
console.log(`src/data/portraitCredits.ts — ${credits.length} credits`);
